// Fresh local continuum Fourier screen. No native/global evolution.
#define Q_FOLLOWUP_NO_MAIN
#include "old_fourier.cpp"
#include "early_feedback.hpp"
#include <fstream>
#include <type_traits>
using Raw=std::array<D,22>;using M22=std::array<std::array<C,22>,22>;
const int raw_index[20]={18,0,7,17,19,20,21,1,2,3,4,5,8,9,10,11,12,14,15,16};
const int ri[6]={0,0,0,1,1,2},rj[6]={0,1,2,1,2,2};
template<class T> hyp::GaugeRHSParts<T> BoundGauge(const hyp::LayerPoint<T>&p,const hyp::Z4cJet<T>&u,double a,int form){
 hyp::LayerGaugeParameters g;g.scri_lapse_damping=1/a;
 if(form<3)return qnf::Gauge(p,u,g,{.85,.95,form?5.:0.,form==2});
 if(form==4||form==6)return earlynf::Gauge(p,u,g,{form==4?5.:3.,0});
 if(form==5)return qnf::Gauge(p,u,g,{.85,.95,3.,true});
 g.physical_trace_lapse=true;g.preferred_source=false;auto q=hyp::InteriorLayerGauge(p,u,g);
 const T W=hyp::LayerCoefficients(p.radius,u.alpha.value,g).weight;
 if(W>T(0)){const auto live=hyp::Geometry(u.metric),ref=hyp::Geometry(p.state.metric);T norm{},Ghat{},dG{};
  for(int i=0;i<3;++i){norm+=p.domega[i]*p.domega[i];for(int j=0;j<3;++j){const T w=p.domega[i]*p.domega[j];Ghat+=p.state.chi.value*ref.inverse[i][j]*w;dG+=((u.chi.value-p.state.chi.value)*ref.inverse[i][j]+u.chi.value*(live.inverse[i][j]-ref.inverse[i][j]))*w;}}
  const double eta=1.5/(a*a),c=1/(3*a);for(int i=0;i<3;++i)q.pole.beta[i]-=eta*W*((u.beta.value[i]-p.beta[i])-c*p.domega[i]*dG/(Kokkos::sqrt(norm)*Ghat));}
 return q;
}
template<class T> struct Result{hyp::Z4cRHS<T>f{};hyp::GaugeRHS<T>g{};};
template<class T> Result<T> Actual(const hyp::LayerPoint<T>&p,const hyp::Z4cJet<T>&u,double a,int form){Result<T>out;const auto omega=[&](){hyp::OmegaJet<T>o{};o.omega=p.omega;for(int i=0;i<3;++i){o.gradient[i]=p.domega[i];for(int j=0;j<3;++j)o.hessian[i][j]=p.omega_hessian[i][j];}hyp::SetStationaryOmegaNormal(u.alpha.value,u.beta.value,u.alpha.d,u.beta.d,o);return o;}();
 if(!hyp::AssembleInterior(hyp::ConformalRHS(u,omega,T(10)/u.alpha.value,T(0)),omega.omega,out.f)||!qnf::Assemble(BoundGauge(p,u,a,form),p.omega,out.g))throw std::runtime_error("invalid actual22 source");return out;}
template<class T> std::array<T,22> Pack(const Result<T>&out){std::array<T,22>v{};v[0]=out.f.chi;v[7]=out.f.trace;v[17]=out.f.theta;v[18]=out.g.alpha;for(int k=0;k<6;++k){v[1+k]=out.f.metric[ri[k]][rj[k]];v[8+k]=out.f.a[ri[k]][rj[k]];}for(int i=0;i<3;++i){v[14+i]=out.f.lambda[i];v[19+i]=out.g.beta[i];}return v;}
Raw Values(const Jet&u){Raw v{};v[0]=u.chi.value;v[7]=u.trace.value;v[17]=u.theta.value;v[18]=u.alpha.value;for(int k=0;k<6;++k){v[1+k]=u.metric.g[ri[k]][rj[k]];v[8+k]=u.a.k[ri[k]][rj[k]];}for(int i=0;i<3;++i){v[14+i]=u.lambda.value[i];v[19+i]=u.beta.value[i];}return v;}
void SeedRaw(Jet&u,int field,const J&z){if(field==0)Scalar(u.chi,z);if(field==7)Scalar(u.trace,z);if(field==17)Scalar(u.theta,z);if(field==18)Scalar(u.alpha,z);if(field>=1&&field<=6){const int k=field-1;SetMetric(u,ri[k],rj[k],Metric(u,ri[k],rj[k])+z);}if(field>=8&&field<=13){const int k=field-8;SetA(u,ri[k],rj[k],A(u,ri[k],rj[k])+z);}if(field>=14&&field<=16)Vector(u.lambda,field-14,z);if(field>=19)Vector(u.beta,field-19,z);}
J Phase(double k,const std::array<double,3>&n,int phase,double amplitude=1,bool dual=true){J z(dual?D(0,phase?0:amplitude):D(phase?0:amplitude));for(int i=0;i<3;++i){z.d[i]=dual?D(0,phase?amplitude*k*n[i]:0):D(phase?amplitude*k*n[i]:0);for(int j=0;j<3;++j)z.dd[i][j]=dual?D(0,phase?0:-amplitude*k*k*n[i]*n[j]):D(phase?0:-amplitude*k*k*n[i]*n[j]);}return z;}
std::array<double,2> InputNormals(const Jet&u){const J x=Metric(u,0,0),y=Metric(u,0,1),z=Metric(u,0,2),w=Metric(u,1,1),v=Metric(u,1,2),t=Metric(u,2,2);const J det=x*(w*t-v*v)-y*(y*t-z*v)+z*(y*v-z*w);J tr=((w*t-v*v)*A(u,0,0)+J(D(2))*(z*v-y*t)*A(u,0,1)+J(D(2))*(y*v-z*w)*A(u,0,2)+(x*t-z*z)*A(u,1,1)+J(D(2))*(y*z-x*v)*A(u,1,2)+(x*w-y*y)*A(u,2,2))/det;
 double m=std::abs(det.v.d),a=std::abs(tr.v.d);for(int i=0;i<3;++i){m=std::max(m,std::abs(det.d[i].d));a=std::max(a,std::abs(tr.d[i].d));for(int j=0;j<3;++j)m=std::max(m,std::abs(det.dd[i][j].d));}return {m,a};}
std::array<double,2> OutputNormals(const Jet&u,const Result<D>&f){const auto geo=hyp::Geometry(u.metric);D m{},a{};for(int i=0;i<3;++i)for(int j=0;j<3;++j){m+=geo.inverse[i][j]*f.f.metric[i][j];a+=geo.inverse[i][j]*f.f.a[i][j];for(int k=0;k<3;++k)for(int l=0;l<3;++l)a-=geo.inverse[i][k]*geo.inverse[j][l]*u.a.k[k][l]*f.f.metric[i][j];}return {m.d,a.d};}
struct Matrices{M22 raw{};M chart{};double input_norm=0,output_norm=0,frozen_lift_derivative_normal=0;};
std::array<std::array<double,20>,22> LiftValues(const hyp::LayerPoint<double>&p){std::array<std::array<double,20>,22>B{};for(int col=0;col<20;++col){auto u=Lift(p.state);Seed(u,col,J(D(0,1)));Consistent(u);const auto v=Values(u);for(int i=0;i<22;++i)B[i][col]=v[i].d;}return B;}
Matrices Build(const hyp::LayerPoint<double>&p,double a,int form,double k,const std::array<double,3>&n){Matrices out;const auto pd=Reference(p);const auto B=LiftValues(p);
 for(int phase=0;phase<2;++phase){const C factor=phase?I:C(1);const auto seed=Phase(k,n,phase);
 for(int col=0;col<22;++col){auto u=Lift(p.state);SeedRaw(u,col,seed);const auto f=Pack(Actual(pd,u,a,form));for(int i=0;i<22;++i)out.raw[i][col]+=factor*f[i].d;}
 for(int col=0;col<20;++col){auto u=Lift(p.state);Seed(u,col,seed);Consistent(u);const auto f=Actual(pd,u,a,form);const auto v=Pack(f);double scale=1;for(auto z:v)scale=std::max(scale,std::abs(z.d));const auto ni=InputNormals(u),no=OutputNormals(u,f);const double jet_scale=1+k*k;out.input_norm=std::max({out.input_norm,ni[0]/jet_scale,ni[1]/jet_scale});out.output_norm=std::max({out.output_norm,std::abs(no[0])/scale,std::abs(no[1])/scale});for(int i=0;i<20;++i)out.chart[i][col]+=factor*v[raw_index[i]].d;
 auto frozen=Lift(p.state);for(int raw=0;raw<22;++raw)SeedRaw(frozen,raw,Phase(k,n,phase,B[raw][col]));const auto nf=InputNormals(frozen);out.frozen_lift_derivative_normal=std::max({out.frozen_lift_derivative_normal,nf[0]/jet_scale,nf[1]/jet_scale});}}
 return out;}
hyp::Z4cJet<double> Double(const Jet&u){hyp::Z4cJet<double>b{};auto scalar=[](auto&a,const auto&v){a.value=v.value.v;for(int i=0;i<3;++i){a.d[i]=v.d[i].v;for(int j=0;j<3;++j)a.dd[i][j]=v.dd[i][j].v;}};scalar(b.chi,u.chi);scalar(b.alpha,u.alpha);scalar(b.trace,u.trace);scalar(b.theta,u.theta);for(int i=0;i<3;++i){b.beta.value[i]=u.beta.value[i].v;b.lambda.value[i]=u.lambda.value[i].v;for(int j=0;j<3;++j){b.beta.d[j][i]=u.beta.d[j][i].v;b.lambda.d[j][i]=u.lambda.d[j][i].v;b.metric.g[i][j]=u.metric.g[i][j].v;b.a.k[i][j]=u.a.k[i][j].v;for(int k=0;k<3;++k){b.beta.dd[k][j][i]=u.beta.dd[k][j][i].v;b.lambda.dd[k][j][i]=u.lambda.dd[k][j][i].v;b.metric.dg[k][i][j]=u.metric.dg[k][i][j].v;b.a.dk[k][i][j]=u.a.dk[k][i][j].v;for(int l=0;l<3;++l)b.metric.ddg[k][l][i][j]=u.metric.ddg[k][l][i][j].v;}}}return b;}
void Binding(){double assembly_error=0,normal_value=0;double error[3]{},raw_error[3]{},chart_error[3]{};int cases=0;const std::array<double,3>n={.36,-.48,.8};hyp::LayerReference<double>ref(1,.5,{true,.05,.95});for(double r:{.45,.8,.9,.98}){const auto p=ref.At(r,0,0);for(int form=0;form<7;++form){auto live=Lift(p.state);Seed(live,0,J(D(.02)));Seed(live,1,J(D(.01)));Seed(live,4,J(D(-.01)));Seed(live,7,J(D(.005)));Consistent(live);const auto gd=BoundGauge(Reference(p),live,.5,form);hyp::GaugeRHS<D>g0{};hyp::AssembleGaugeInterior(gd,D(p.omega),g0);hyp::GaugeRHS<D>g{};qnf::Assemble(gd,D(p.omega),g);for(int i=0;i<3;++i)assembly_error=std::max(assembly_error,std::abs(g.beta[i].v-g0.beta[i].v-gd.pole.beta[i].v/p.omega));
 for(int chart=0;chart<2;++chart)for(int col=0;col<(chart?20:22);++col)for(int phase=0;phase<2;++phase){auto u=Lift(p.state);if(chart){Seed(u,col,Phase(4,n,phase));Consistent(u);}else SeedRaw(u,col,Phase(4,n,phase));const auto exact=Pack(Actual(Reference(p),u,.5,form));for(int level=0;level<3;++level){const double eps=std::pow(10.,-3-level);std::array<double,22>values[2];for(int sign=0;sign<2;++sign){auto v=Lift(p.state);if(chart){Seed(v,col,Phase(4,n,phase,sign?eps:-eps,false));Consistent(v);}else SeedRaw(v,col,Phase(4,n,phase,sign?eps:-eps,false));values[sign]=Pack(Actual(p,Double(v),.5,form));}double numerator=0,denominator=1;for(int i=0;i<22;++i){numerator+=std::pow((values[1][i]-values[0][i])/(2*eps)-exact[i].d,2);denominator+=exact[i].d*exact[i].d;}const double e=std::sqrt(numerator/denominator);error[level]=std::max(error[level],e);(chart?chart_error:raw_error)[level]=std::max((chart?chart_error:raw_error)[level],e);}++cases;}}
 }
 std::cout<<"{\"cases\":"<<cases<<",\"single_beta_pole_assembly_error\":"<<assembly_error<<",\"relative_FD_error\":["<<error[0]<<','<<error[1]<<','<<error[2]<<"],\"raw22_relative_FD_error\":["<<raw_error[0]<<','<<raw_error[1]<<','<<raw_error[2]<<"],\"intrinsic20_relative_FD_error\":["<<chart_error[0]<<','<<chart_error[1]<<','<<chart_error[2]<<"]}";
}
template<int N> void Binary(std::ofstream&out,const std::array<std::array<C,N>,N>&m){for(const auto&r:m)for(auto z:r){const double pair[2]={z.real(),z.imag()};out.write(reinterpret_cast<const char*>(pair),sizeof(pair));}}
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("matrix output filename required");std::ofstream binary(argv[1],std::ios::binary);if(!binary)throw std::runtime_error("cannot create matrix payload");std::cout<<std::setprecision(17)<<"{\"rows\":[";bool first=true;double input=0,output=0,frozen_normal=0;for(double a:{.5,.75,1.,2.}){hyp::LayerReference<double>ref(1,a,{true,.05,.95});for(double r:{.45,.65,.8,.85,.9,.95,.98})for(double k:{0.,4.,16.,64.,256.})for(int dir=0;dir<2;++dir)for(int form=0;form<7;++form){const auto p=ref.At(r,0,0);const std::array<double,3>n=dir?std::array<double,3>{.36,-.48,.8}:std::array<double,3>{1,0,0};const auto m=Build(p,a,form,k,n);Binary<22>(binary,m.raw);Binary<20>(binary,m.chart);input=std::max(input,m.input_norm);output=std::max(output,m.output_norm);frozen_normal=std::max(frozen_normal,m.frozen_lift_derivative_normal);double physical=0;const auto g=hyp::Geometry(p.state.metric);for(int i=0;i<3;++i)for(int j=0;j<3;++j)physical+=p.state.chi.value*g.inverse[i][j]*n[i]*n[j];const double kbar=k*std::sqrt(physical);if(!first)std::cout<<',';first=false;std::cout<<"{\"a\":"<<a<<",\"r\":"<<r<<",\"Omega\":"<<p.omega<<",\"k\":"<<k<<",\"dir\":"<<dir<<",\"form\":"<<form<<",\"k_penrose\":"<<kbar<<",\"k_physical_spatial\":"<<p.omega*kbar<<"}";}}
 binary.close();std::cout<<"],\"lifts\":[";first=true;for(double a:{.5,.75,1.,2.}){hyp::LayerReference<double>ref(1,a,{true,.05,.95});for(double r:{.45,.65,.8,.85,.9,.95,.98}){if(!first)std::cout<<',';first=false;const auto p=ref.At(r,0,0);const auto B=LiftValues(p);const auto geo=hyp::Geometry(p.state.metric);hyp::LayerGaugeParameters par;par.scri_lapse_damping=1/a;std::cout<<"{\"a\":"<<a<<",\"r\":"<<r<<",\"alpha\":"<<p.alpha<<",\"chi\":"<<p.state.chi.value<<",\"Omega\":"<<p.omega<<",\"W\":"<<hyp::LayerCoefficients(p.radius,p.alpha,par).weight<<",\"Vlate\":"<<hyp::SmoothCutoff(p.radius,.85,.95).value<<",\"beta\":[";for(int i=0;i<3;++i)std::cout<<(i?",":"")<<p.beta[i];std::cout<<"],\"dOmega\":[";for(int i=0;i<3;++i)std::cout<<(i?",":"")<<p.domega[i];std::cout<<"],\"inverse\":[";for(int i=0;i<3;++i){if(i)std::cout<<',';std::cout<<'[';for(int j=0;j<3;++j)std::cout<<(j?",":"")<<geo.inverse[i][j];std::cout<<']';}std::cout<<"],\"B\":[";for(int i=0;i<22;++i){if(i)std::cout<<',';std::cout<<'[';for(int j=0;j<20;++j)std::cout<<(j?",":"")<<B[i][j];std::cout<<']';}std::cout<<"]}";}}
 std::cout<<"],\"normal_gate\":{\"intrinsic_input_consumed_jet_scaled\":"<<input<<",\"intrinsic_output_scaled\":"<<output<<",\"value_frozen_B_derivative_normal_scaled\":"<<frozen_normal<<"},\"binding\":";Binding();std::cout<<"}\n";
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
